const names=["Vercel Inc.","Notion Labs, Inc.","Figma, Inc.","Rippling People Center, Inc.","Anthropic PBC"];
const out={};
for(const n of names){
  const r=await page.evaluate(async(n)=>{
    const res=await fetch('/api/Records/businesssearch',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({SEARCH_VALUE:n,SEARCH_FILTER_TYPE_ID:'0',SEARCH_TYPE_ID:'1',FILING_TYPE_ID:'',STATUS_ID:'',FILING_DATE:{start:null,end:null},CORPORATION_BANKRUPTCY_YN:false,CORPORATION_LEGAL_PROCEEDINGS_YN:false,OFFICER_OBJECT:{FIRST_NAME:'',MIDDLE_NAME:'',LAST_NAME:''},NUMBER_OF_FEMALE_DIRECTORS:'99',NUMBER_OF_UNDERREPRESENTED_DIRECTORS:'99',COMPENSATION_FROM:'',COMPENSATION_TO:'',SHARES_YN:false,OPTIONS_YN:false,BANKRUPTCY_YN:false,FRAUD_YN:false,LOANS_YN:false,AUDITOR_NAME:''})});
    return {status:res.status,text:(await res.text()).slice(0,3000)};
  },n);
  out[n]=r;
}
console.log(JSON.stringify(out,null,1));
EOF
firecrawl interact --timeout 120 --code "$(cat /tmp/s.js)" 2>&1 | head -80

